PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('tenant','landlord','staff')),password_hash TEXT,activation_hash TEXT,activation_expires INTEGER,created INTEGER NOT NULL,disabled INTEGER NOT NULL DEFAULT 0,is_test INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES accounts(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS leases(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES accounts(id),address TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,deposit_cents INTEGER NOT NULL CHECK(deposit_cents>=0),refund_date TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members(lease_id TEXT NOT NULL REFERENCES leases(id),user_id TEXT NOT NULL REFERENCES accounts(id),role TEXT NOT NULL CHECK(role IN('tenant','landlord')),PRIMARY KEY(lease_id,user_id),UNIQUE(lease_id,role));
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),email TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,accepted_by TEXT REFERENCES accounts(id),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),kind TEXT NOT NULL CHECK(kind IN('movein','moveout')),created INTEGER NOT NULL,UNIQUE(lease_id,kind));
CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),uploaded_by TEXT NOT NULL REFERENCES accounts(id),sha256 TEXT NOT NULL,mime TEXT NOT NULL,bytes BLOB,received INTEGER NOT NULL,capture_claim TEXT,purged INTEGER);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES records(id),seq INTEGER NOT NULL,parent_id TEXT REFERENCES versions(id),base_id TEXT REFERENCES versions(id),opened INTEGER NOT NULL,deadline INTEGER NOT NULL,created INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES accounts(id),body TEXT NOT NULL,digest TEXT NOT NULL,UNIQUE(record_id,seq));
CREATE TABLE IF NOT EXISTS decisions(version_id TEXT NOT NULL REFERENCES versions(id),user_id TEXT NOT NULL REFERENCES accounts(id),kind TEXT NOT NULL CHECK(kind IN('confirm','dispute','refuse')),note TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(version_id,user_id));
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),received_date TEXT NOT NULL,note TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES accounts(id),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cases(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),requester TEXT NOT NULL REFERENCES accounts(id),subject TEXT NOT NULL,photo_ids TEXT NOT NULL,assignee TEXT REFERENCES accounts(id),status TEXT NOT NULL DEFAULT 'open',hold INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS replies(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id),author TEXT NOT NULL REFERENCES accounts(id),body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audits(id INTEGER PRIMARY KEY,actor TEXT,action TEXT NOT NULL,object_id TEXT NOT NULL,at INTEGER NOT NULL,detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES accounts(id),lease_id TEXT,kind TEXT NOT NULL,reason TEXT NOT NULL,at INTEGER NOT NULL,is_test INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS surveys(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES accounts(id),pu TEXT NOT NULL,peou TEXT NOT NULL,created INTEGER NOT NULL,is_test INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS checks(id TEXT PRIMARY KEY,lease_id TEXT NOT NULL REFERENCES leases(id),user_id TEXT NOT NULL REFERENCES accounts(id),kind TEXT NOT NULL,object TEXT NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL,result TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS versions_no_update BEFORE UPDATE ON versions BEGIN SELECT RAISE(ABORT,'immutable_version'); END;
CREATE TRIGGER IF NOT EXISTS versions_no_delete BEFORE DELETE ON versions BEGIN SELECT RAISE(ABORT,'immutable_version'); END;
CREATE TRIGGER IF NOT EXISTS decisions_no_update BEFORE UPDATE ON decisions BEGIN SELECT RAISE(ABORT,'immutable_decision'); END;
CREATE TRIGGER IF NOT EXISTS decisions_no_delete BEFORE DELETE ON decisions BEGIN SELECT RAISE(ABORT,'immutable_decision'); END;
CREATE TRIGGER IF NOT EXISTS photos_no_overwrite BEFORE UPDATE ON photos WHEN NOT(OLD.bytes IS NOT NULL AND NEW.bytes IS NULL AND NEW.purged IS NOT NULL AND OLD.id=NEW.id AND OLD.sha256=NEW.sha256 AND OLD.lease_id=NEW.lease_id AND OLD.uploaded_by=NEW.uploaded_by AND OLD.mime=NEW.mime AND OLD.received=NEW.received AND OLD.capture_claim IS NEW.capture_claim AND OLD.purged IS NULL) BEGIN SELECT RAISE(ABORT,'immutable_photo'); END;
CREATE TRIGGER IF NOT EXISTS photos_no_delete BEFORE DELETE ON photos BEGIN SELECT RAISE(ABORT,'use_retention_purge'); END;
CREATE TRIGGER IF NOT EXISTS audits_no_update BEFORE UPDATE ON audits BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TRIGGER IF NOT EXISTS audits_no_delete BEFORE DELETE ON audits BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE INDEX IF NOT EXISTS versions_record ON versions(record_id,seq DESC);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE INDEX IF NOT EXISTS photos_lease ON photos(lease_id);
CREATE INDEX IF NOT EXISTS audits_object ON audits(object_id,at);
